-- pay_waffo_release_due(integer)
CREATE OR REPLACE FUNCTION public.pay_waffo_release_due(p_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE row record; i integer; n integer:=0;
BEGIN
 IF p_limit<1 OR p_limit>500 THEN RAISE EXCEPTION 'PAY_WAFFO_LIMIT_INVALID'; END IF;
 FOR row IN SELECT o.id,o.billing_cycle FROM payment_orders o JOIN user_subscriptions s ON s.id=o.subscription_id
   WHERE o.payment_method IS NOT NULL AND pay_method_mode_allowed(o.payment_channel,o.payment_mode) AND (o.billing_cycle='yearly' OR o.billing_cycle='monthly' AND o.method_transition='wallet_renewal')
   AND o.payment_status='paid' AND o.status='completed' AND o.fulfilled_at IS NOT NULL
   AND s.credit_release_terminated_at IS NULL
   AND EXISTS(SELECT 1 FROM profiles p WHERE p.id=o.user_id AND p.status='active' AND p.is_deleted='false')
   AND NOT EXISTS(SELECT 1 FROM account_erasure_requests WHERE profile_id=o.user_id) AND EXISTS(SELECT 1 FROM generate_series(1,CASE o.billing_cycle WHEN 'yearly' THEN 12 ELSE 1 END) idx
     WHERE ((o.entitlement_start AT TIME ZONE 'UTC')+make_interval(months=>idx-1)) AT TIME ZONE 'UTC'<=pay_stripe_test_clock_now(o.id)
     AND NOT EXISTS(SELECT 1 FROM subscription_credit_grants g WHERE g.source_order_id=o.id AND (g.period_index=idx OR o.billing_cycle='monthly'
       AND g.grant_period_key='payment:'||o.id::text||':01')))
   ORDER BY o.entitlement_start,o.id LIMIT p_limit LOOP
  FOR i IN 1..CASE row.billing_cycle WHEN 'yearly' THEN 12 ELSE 1 END LOOP n:=n+pay_waffo_grant_period(row.id,i); END LOOP;
 END LOOP;
 RETURN n;
END $function$;
